package io.knowledgebrain.collaboration;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.collaboration.api.enabled",havingValue="true")
@RequestMapping("/api/groups/{groupId}/studies/{studyId}/assignments/{assignmentId}/submissions/{submissionId}")
final class RubricGradingController {
 private final RubricGradingStore store;private final StudyController gate;private final MeterRegistry metrics;
 RubricGradingController(RubricGradingStore store,StudyController gate,MeterRegistry metrics){this.store=store;this.gate=gate;this.metrics=metrics;}
 @GetMapping("/rubric-grade") ResponseEntity<?> get(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());gate.empty(r);var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var submission=GroupInput.id(submissionId);var a=gate.participant(group,r,false,gate.trace(r));var v=store.get(group,a.space(),study,assignment,submission,a.actor(),a.role().equals("OWNER"));metrics.counter("brain.collaboration.rubric.grading.reads","type","current").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(SubmissionGradeController.tag(v.grade()==null?0:v.grade().version())).body(v);
 }
 @PutMapping("/rubric-grade") ResponseEntity<?> change(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var submission=GroupInput.id(submissionId);String trace=gate.trace(r);var a=gate.access(group,r,true,trace);var expected=SubmissionGradeController.expected(r);var input=RubricGradingInput.parse(gate.jsonBody(r));var v=store.change(group,a.space(),study,assignment,submission,a.actor(),expected,input,trace.substring(3,35));metrics.counter("brain.collaboration.rubric.grading.changes","mode",input.mode()).increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("rubric_grading grade_id={} trace_id={}",v.grade().gradeId(),trace.substring(3,35));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).eTag(SubmissionGradeController.tag(v.grade().version())).body(v);
 }
 @GetMapping("/grade/revisions/{gradeVersion}/rubric-assessment") ResponseEntity<?> basis(@PathVariable String groupId,@PathVariable String studyId,@PathVariable String assignmentId,@PathVariable String submissionId,@PathVariable String gradeVersion,HttpServletRequest r)throws IOException{
  gate.query(r,Set.of());gate.empty(r);var group=GroupInput.id(groupId);var study=GroupInput.id(studyId);var assignment=GroupInput.id(assignmentId);var submission=GroupInput.id(submissionId);long version=gate.number(gradeVersion,0,Long.MAX_VALUE);var a=gate.participant(group,r,false,gate.trace(r));metrics.counter("brain.collaboration.rubric.grading.reads","type","version").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Collections.singletonMap("assessment",store.forVersion(group,a.space(),study,assignment,submission,version,a.actor(),a.role().equals("OWNER"))));
 }
}
